"use strict";
const assert = require("node:assert/strict");
const fs = require("node:fs");
const crypto = require("node:crypto");
const http = require("node:http");
const {spawn} = require("node:child_process");
const expected = {"source_commit":"7fe5e1342e586dd994020683c3e3fb227d4b287a","manifest_sha256":"69881e708c01a0b7f4345f654fb662139cee9542840f63c5beab2d66c8ff71cd","hook_sha256":"d015ee6ecb9d3e1b42d758b61f759e6201b5539d96cdd5a8f1ca0a519b1a465c","history_sha256":"2b73d028588fbeb134de85e82f0605773ce62cf33fafe2216dde470ccaa2738b"};
const hash = data => crypto.createHash("sha256").update(data).digest("hex");
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  assert.equal(process.getuid(), 1000);
  assert.equal(process.getgid(), 1000);
  assert.equal(process.env.OCEAN_V1_EXPECT_RESEARCH_API, "true");
  const raw = fs.readFileSync("/opt/ocean/source-manifest.json");
  assert.equal(hash(raw), expected.manifest_sha256);
  const manifest = JSON.parse(raw);
  assert.equal(manifest.source_commit, expected.source_commit);
  assert.equal(manifest.source_files["frontend-v1/src/research-answers.tsx"], expected.hook_sha256);
  assert.equal(manifest.source_files["frontend-v1/src/research-answer-history.ts"], expected.history_sha256);
  assert.equal(manifest.synthetic_preview_graph_included, false);
  assert.equal(manifest.credentials_or_generated_files_included, false);
  for (const name of ["frontend-v1/src/fixtures.ts", "frontend-v1/src/adapter.ts", "frontend-v1/src/v1-entry.tsx", "frontend-v1/src/research-app.tsx"]) assert.equal(manifest.source_files[name], undefined);
  for (const [name, digest] of [["serving-frontend-adapter.cjs", manifest.serving_adapter_sha256], ["beta-wait-api.cjs", manifest.startup_gate_sha256]]) {
    const file = "/opt/ocean/" + name;
    assert.equal(hash(fs.readFileSync(file)), digest);
    assert.equal(fs.statSync(file).mode & 0o777, 0o444);
  }
  assert(fs.statSync("/opt/ocean/hosting/server.js").isFile());
  assert(fs.readdirSync("/opt/ocean/hosting/.next/static").length > 0);
  let healthCalls = 0;
  const api = http.createServer((req, res) => {
    if (req.url === "/health/live") {
      healthCalls += 1;
      res.writeHead(200, {"content-type":"application/json"});
      res.end(JSON.stringify({status:"live", execution_enabled:true}));
    } else { res.writeHead(404); res.end(); }
  });
  await new Promise((resolve, reject) => { api.once("error", reject); api.listen(8000, "127.0.0.1", resolve); });
  const env = {...process.env, K_SERVICE:"ocean-v1-beta-serving", DEPLOYMENT_ENV:"production", AUTH_MODE:"required", ENABLE_MOCK_LOGIN:"false", PERSIST_LOCAL_CHAT:"false", V1_PUBLIC_ORIGIN:"https://beta.oceaninfobio.com", AUTH_URL:"https://beta.oceaninfobio.com", V1_API_ORIGIN:"http://127.0.0.1:8000", V1_AUTH_SECRET:"a".repeat(64), V1_INTERNAL_AUTH_SECRET:"b".repeat(64), V1_INTERNAL_AUTH_ISSUER:"ocean-v1-frontend", V1_INTERNAL_AUTH_AUDIENCE:"ocean-v1-api", V1_GOOGLE_CLIENT_ID:"synthetic-client.apps.googleusercontent.com", V1_GOOGLE_CLIENT_SECRET:"synthetic-provider-secret", OCEAN_V1_EXPECT_RESEARCH_API:"true", HOSTNAME:"127.0.0.1", PORT:"8080", NODE_ENV:"production", NEXT_TELEMETRY_DISABLED:"1"};
  const child = spawn(process.execPath, ["--require", "/opt/ocean/serving-frontend-adapter.cjs", "/opt/ocean/beta-wait-api.cjs"], {env, stdio:["ignore", "pipe", "pipe"]});
  let output = "", failure;
  child.on("error", error => { failure = error; });
  for (const stream of [child.stdout, child.stderr]) stream.on("data", value => { output = (output + value).slice(-20000); });
  try {
    const deadline = Date.now() + 25000;
    while (!output.includes("Ready in") && Date.now() < deadline) {
      if (failure) throw failure;
      if (child.exitCode !== null) throw new Error("Packaged frontend exited: " + output);
      await delay(100);
    }
    assert(output.includes("Independent beta API ready; starting frontend"), output);
    assert(output.includes("Ready in"), output);
    const response = await new Promise((resolve, reject) => {
      const request = http.get({host:"127.0.0.1", port:8080, path:"/login", headers:{host:"beta.oceaninfobio.com", "x-forwarded-host":"beta.oceaninfobio.com", "x-forwarded-proto":"https", "x-forwarded-port":"443"}}, res => {
        let body = "";
        res.setEncoding("utf8");
        res.on("data", chunk => { body += chunk; if (body.length > 1000000) res.destroy(); });
        res.on("error", reject);
        res.on("end", () => resolve({status:res.statusCode, body}));
      });
      request.setTimeout(15000, () => request.destroy(new Error("Packaged login timeout")));
      request.on("error", reject);
    });
    assert.equal(response.status, 200);
    assert(response.body.includes("Sign in with Google"));
    assert(healthCalls >= 1);
    console.log(JSON.stringify({result:"passed", source_commit:manifest.source_commit, manifest_sha256:expected.manifest_sha256, uid:process.getuid(), gid:process.getgid(), expected_research_api:true, startup_health_execution_enabled:true, packaged_startup:true, packaged_login_status:response.status, network:"none", real_credentials:false}));
  } finally {
    child.kill("SIGTERM");
    const deadline = Date.now() + 3000;
    while (child.exitCode === null && child.signalCode === null && Date.now() < deadline) await delay(50);
    if (child.exitCode === null && child.signalCode === null) child.kill("SIGKILL");
    api.closeAllConnections();
    await new Promise(resolve => api.close(resolve));
  }
})().catch(error => { console.error(error); process.exitCode = 1; });
'
